css:
:root{--ink:#0b0b0a;--coal:#151513;--panel:#1a1914;--gold:#cda855;--gold-l:#e3c88a;--gold-d:#7d6530;--bone:#f4eedf;--mute:#a9a291;--ivory:#fff9f7;box-sizing:border-box}
html{scroll-padding-top:130px;scroll-behavior:smooth}
*,*:before,*:after{box-sizing:inherit}
body{margin:0;background:var(--ink);color:var(--bone);font:300 1.0625rem/1.8 var(--font-jost, "Jost"),system-ui,sans-serif;-webkit-font-smoothing:antialiased}
h1,h2,h3{font-family:var(--font-cormorant, "Cormorant Garamond"),Georgia,serif;font-weight:500;margin:0;line-height:1.1}
a{color:var(--gold-l)}
a:focus-visible,button:focus-visible{outline:2px solid var(--gold);outline-offset:3px}
img{max-width:100%;display:block}
.wrap{max-width:1120px;margin:0 auto;padding:0 28px}
.hero{background:radial-gradient(ellipse 70% 70% at 70% 40%,#2a2314 0,#0b0b0a 70%);padding:72px 0}
.frame{position:relative;max-width:960px;margin:0 auto;padding:56px 32px 60px;text-align:center;border:1px solid var(--gold-d)}
.frame:before{content:"";position:absolute;inset:8px;border:1px solid rgba(205,168,85,.35);pointer-events:none}
.logo{width:min(680px,100%);height:auto;margin:0 auto 28px;animation:fade 1.1s ease-out both}
@keyframes fade{from{opacity:0;transform:scale(.98)}to{opacity:1;transform:none}}
.hero h1{font-size:clamp(1.8rem,3.6vw,2.6rem);font-style:italic;font-weight:400;color:var(--gold-l);margin-bottom:16px}
.hero p{color:var(--mute);max-width:34em;margin:0 auto 32px}
.rule{width:72px;height:1px;background:var(--gold);margin:0 0 26px;position:relative}
.rule:after{content:"";position:absolute;left:80px;top:-2px;width:5px;height:5px;background:var(--gold);transform:rotate(45deg)}
.btn{display:inline-block;padding:14px 34px;font-size:.8rem;font-weight:500;letter-spacing:.18em;text-transform:uppercase;text-decoration:none;color:var(--ink);background:var(--gold);border:1px solid var(--gold);transition:background .25s,color .25s}
.btn:hover{background:transparent;color:var(--gold)}
.btn.sm{padding:11px 26px}
.btn.dark{background:var(--ink);color:var(--gold);border-color:var(--ink)}
.btn.dark:hover{background:transparent;color:var(--ink);border-color:var(--ink)}
section{padding:100px 0}
.title{margin-bottom:52px}
.title.tight{margin-bottom:28px}
.title h2{font-size:clamp(2.2rem,4.4vw,3.2rem)}
.title .rule{margin:0 0 20px}
.about{background:var(--coal);border-top:1px solid var(--gold-d);border-bottom:1px solid var(--gold-d)}
.split{display:grid;grid-template-columns:1fr 1fr;gap:80px;align-items:center}
.about p{color:var(--mute);margin:0 0 18px}
.collage{position:relative;height:440px}
.collage .a{position:absolute;right:0;top:0;width:68%;border:1px solid var(--gold-d);padding:8px;background:var(--ink)}
.collage .b{position:absolute;left:0;bottom:0;width:50%;border:1px solid var(--gold-d);padding:8px;background:var(--ink);box-shadow:0 14px 30px rgba(0,0,0,.6)}
.services{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));border-top:1px solid var(--gold-d);border-left:1px solid var(--gold-d)}
.cell{padding:42px 28px;border-right:1px solid var(--gold-d);border-bottom:1px solid var(--gold-d);text-align:center;transition:background .3s}
.cell:hover{background:var(--panel)}
.cell svg{height:44px;width:auto;max-width:52px;color:var(--gold);fill:currentColor;stroke:none;margin:0 auto 20px}
.cell h3{font-size:1.8rem;margin-bottom:10px}
.cell p{margin:0;color:var(--mute);font-size:.95rem;line-height:1.65}
.branches{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:32px}
.card{background:var(--ivory);color:#1d1b17;text-align:center;padding:44px 30px 40px;display:flex;flex-direction:column;align-items:center;outline:1px solid var(--gold);outline-offset:-10px}
.card img{height:104px;width:auto;margin-bottom:22px;mix-blend-mode:multiply}
.card h3{font-size:1.8rem;margin-bottom:10px}
.card p{font-size:.95rem;color:#5b564b;margin:0 0 26px;flex:1}
@media(max-width:860px){
section{padding:68px 0}
.split{grid-template-columns:1fr;gap:44px}
.collage{height:400px}
.frame{padding:40px 18px 44px}
}
@media(max-width:700px){
.wrap{padding:0 18px}
.hero{padding:36px 0}
.logo{margin-bottom:20px}
}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*{animation:none!important;transition:none!important}}
